(()=>{const body=document.body;const paletteButtons=[...document.querySelectorAll('.palette-button')];const sectionLinks=[...document.querySelectorAll('.product-nav a')];const sections=sectionLinks.map(link=>document.querySelector(link.getAttribute('href')));const productBar=document.querySelector('.product-bar');const plannedNote=document.getElementById('plannedNote');let noteTimer=null;let navFrame=null;paletteButtons.forEach(button=>button.addEventListener('click',()=>{body.dataset.theme=button.dataset.palette;paletteButtons.forEach(item=>{const selected=item===button;item.classList.toggle('selected',selected);item.setAttribute('aria-pressed',String(selected));});}));document.querySelectorAll('[data-contact]').forEach(button=>button.addEventListener('click',()=>{if(payloadDialog.open)payloadDialog.close();plannedNote.hidden=false;window.clearTimeout(noteTimer);noteTimer=window.setTimeout(()=>{plannedNote.hidden=true;},3600);}));function updateActiveSection(){navFrame=null;const threshold=productBar.offsetHeight+110;let current=0;sections.forEach((section,index)=>{if(section.getBoundingClientRect().top<=threshold)current=index;});sectionLinks.forEach((link,index)=>{if(index===current)link.setAttribute('aria-current','true');else link.removeAttribute('aria-current');});}
window.addEventListener('scroll',()=>{if(navFrame===null)navFrame=window.requestAnimationFrame(updateActiveSection);},{passive:true});window.addEventListener('resize',updateActiveSection);const payloadDialog=document.getElementById('payloadDialog');const payloadTriggers=[...document.querySelectorAll('[data-payload-open]')];let payloadTrigger=null;let previousOverflow='';payloadTriggers.forEach(button=>button.addEventListener('click',()=>{if(payloadDialog.open)return;payloadTrigger=button;previousOverflow=document.documentElement.style.overflow;document.documentElement.style.overflow='hidden';button.setAttribute('aria-expanded','true');payloadDialog.showModal();payloadDialog.scrollTop=0;}));document.getElementById('payloadClose').addEventListener('click',()=>payloadDialog.close());payloadDialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const focusable=[...payloadDialog.querySelectorAll('button:not([disabled]), [href], [tabindex="0"]')].filter(element=>element.getClientRects().length);const first=focusable[0];const last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});payloadDialog.addEventListener('close',()=>{document.documentElement.style.overflow=previousOverflow;payloadTriggers.forEach(button=>button.setAttribute('aria-expanded','false'));payloadTrigger?.focus({preventScroll:true});});payloadDialog.addEventListener('click',event=>{const box=payloadDialog.getBoundingClientRect();if(event.target===payloadDialog&&(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom))payloadDialog.close();});updateActiveSection();})();document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{const target=document.querySelector(link.getAttribute('href'));if(!target)return;event.preventDefault();target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}));addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo'||event.data.type!=='view-active')return;const dialog=document.getElementById('payloadDialog');if(!event.data.active&&dialog.open)dialog.close();document.getElementById('plannedNote').hidden=true;if(event.data.active){scrollTo({top:0,behavior:'instant'});dispatchEvent(new Event('resize'));}});(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)');const image=document.querySelector('.hero-section__image');const hero=document.querySelector('.hero-section');const productBar=document.querySelector('.product-bar');const root=document.documentElement;const animations=new Set();const revealedSections=new WeakSet();const sectionAnchors=new WeakMap();let active=false;let observer=null;let scrollFrame=null;let entryCount=0;function animate(element,frames,options){if(!element||reduce.matches||!element.animate)return;const animation=element.animate(frames,{easing:'cubic-bezier(.16,1,.3,1)',fill:'backwards',...options});animations.add(animation);animation.finished.then(()=>animations.delete(animation),()=>animations.delete(animation));return animation;}
function cancelMotion(){animations.forEach(animation=>animation.cancel());animations.clear();observer?.disconnect();observer=null;}
function updateScroll(){scrollFrame=null;if(!active)return;const total=Math.max(1,root.scrollHeight-innerHeight);productBar.style.setProperty('--reading-progress',String(Math.min(1,Math.max(0,scrollY/total))));const progress=Math.min(1,Math.max(0,-hero.getBoundingClientRect().top/hero.offsetHeight));image.style.setProperty('--hero-drift',reduce.matches?'0px':(-14*progress).toFixed(2)+'px');}
function scheduleScroll(){if(active&&scrollFrame===null)scrollFrame=requestAnimationFrame(updateScroll);}
function finishSection(element){revealedSections.add(element);observer?.unobserve(sectionAnchors.get(element)||element);element.dataset.motionSeen='true';element.classList.add('no-reveal-motion','is-revealed');element.getAnimations().forEach(animation=>animation.finish());}
function watchSections(){const groups=['.metrics__inner','.applications-section','.technology-inner','.specifications-section','.gallery-section > .page-width','.contact-inner'];const targets=[...document.querySelectorAll(groups.join(','))];const pending=[];const revealTargets=new Map();targets.forEach((element,index)=>{element.dataset.motionOrder=String(index);const anchor=element.querySelector('.section-heading, .technology-heading, .specifications-heading, .gallery-heading, h2')||element;sectionAnchors.set(element,anchor);const bounds=anchor.getBoundingClientRect();if(revealedSections.has(element)||reduce.matches||!('IntersectionObserver'in window)||(bounds.top<innerHeight&&bounds.bottom>0)){finishSection(element);}else{element.classList.add('scroll-reveal');pending.push(anchor);revealTargets.set(anchor,element);}});if(!pending.length)return;void document.body.offsetHeight;observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{const element=revealTargets.get(entry.target);if(!element||!entry.isIntersecting||revealedSections.has(element))return;revealedSections.add(element);observer.unobserve(entry.target);element.dataset.motionSeen='true';element.dataset.motionRevealCount=String(Number(element.dataset.motionRevealCount||0)+1);element.classList.add('is-revealed');});},{threshold:.02,rootMargin:'0px 0px -72px 0px'});pending.forEach(element=>observer.observe(element));}
function entrance(){cancelMotion();entryCount+=1;document.body.dataset.motionEntry=String(entryCount);document.body.dataset.motionMode=reduce.matches?'reduced':'normal';image.style.setProperty('--hero-drift','0px');updateScroll();if(!reduce.matches){animate(image,[{transform:'translate3d(0,0,0) scale(1.13)',filter:'brightness(.82)'},{transform:'translate3d(0,0,0) scale(1.04)',filter:'brightness(1)'}],{duration:1800});animate(document.querySelector('.hero-role'),[{opacity:.3,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:800,delay:120});animate(document.getElementById('product-title'),[{opacity:.4,transform:'translateY(46px)',clipPath:'inset(0 0 90% 0)'},{opacity:1,transform:'translateY(0)',clipPath:'inset(0)'}],{duration:1050,delay:220});animate(document.querySelector('.hero-actions'),[{opacity:.45,transform:'translateY(24px)'},{opacity:1,transform:'translateY(0)'}],{duration:900,delay:480});animate(document.querySelector('.product-bar'),[{transform:'translateY(-10px)'},{transform:'translateY(0)'}],{duration:650});}
watchSections();}
addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo'||event.data.type!=='view-active')return;if(event.data.active){if(!active){active=true;entrance();}}else{active=false;cancelMotion();}});addEventListener('scroll',scheduleScroll,{passive:true});addEventListener('resize',scheduleScroll);reduce.addEventListener('change',()=>{if(active)entrance();});document.addEventListener('focusin',event=>{if(event.target.closest('[data-motion-order]')){const target=event.target.closest('[data-motion-order]');finishSection(target);}});})();addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo'||event.data.type!=='palette')return;const theme=event.data.theme;document.documentElement.dataset.theme=theme;document.body.dataset.theme=theme;document.querySelectorAll('.palette-button').forEach(button=>{button.classList.toggle('selected',button.dataset.palette===theme);button.setAttribute('aria-pressed',String(button.dataset.palette===theme));});});const PRODUCT_LINE="05 Carbon Credit UAV";document.addEventListener('click',event=>{const button=event.target.closest('[data-contact]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const dialog=document.getElementById('payloadDialog');if(dialog&&dialog.open)dialog.close();parent.postMessage({namespace:'ctuav-demo',type:'route',route:'contact',line:PRODUCT_LINE},'*');},true);"use strict";(()=>{document.querySelectorAll('[data-footer-route]').forEach((button)=>button.addEventListener('click',()=>{const route=button.dataset.footerRoute;if(window.ctuavDemo)window.ctuavDemo.navigate(route);else if(parent!==window)parent.postMessage({namespace:'ctuav-demo',type:'route',route},'*');}));})();